  7→export interface CriteriaBatch {
  8→    id: string;
  9→    protocol_id: string;
 10→    protocol_title: string;
 11→    status:
 12→        | 'pending_review'
 13→        | 'in_progress'
 14→        | 'entities_grounded'
 15→        | 'reviewed'
 16→        | 'approved'
 17→        | 'rejected';
 18→    extraction_model: string | null;
 19→    criteria_count: number;
 20→    reviewed_count: number;
 21→    created_at: string;
 22→    updated_at: string;
 23→}
