 25→export interface BatchListResponse {
 26→    items: CriteriaBatch[];
 27→    total: number;
 28→    page: number;
 29→    page_size: number;
 30→    pages: number;
 31→}
 32→
 33→// Field mapping for structured criteria edits (entity/relation/value triplet)
 34→export interface FieldMapping {
 35→    entity: string;
 36→    entity_code?: string;
 37→    entity_system?: string;
 38→    omop_concept_id?: string;
 39→    relation: string;
 40→    value: unknown;
 41→}
 42→
 43→export interface CriterionEntity {
 44→    id: string;
 45→    entity_type: string;
 46→    text: string;
 47→    umls_cui: string | null;
 48→    snomed_code: string | null;
 49→    preferred_term: string | null;
 50→    grounding_confidence: number | null;
 51→}
 52→
 53→export interface Criterion {
 54→    id: string;
 55→    batch_id: string;
 56→    criteria_type: string;
 57→    category: string | null;
 58→    text: string;
 59→    temporal_constraint: Record<string, unknown> | null;
 60→    conditions: Record<string, unknown> | null;
 61→    numeric_thresholds: Record<string, unknown> | null;
 62→    assertion_status: string | null;
 63→    confidence: number;
 64→    source_section: string | null;
 65→    page_number: number | null;
 66→    review_status: string | null;
 67→    entities: CriterionEntity[];
 68→    created_at: string;
 69→    updated_at: string;
 70→}
 71→
 72→export interface ReviewActionRequest {
 73→    action: 'approve' | 'reject' | 'modify';
 74→    reviewer_id: string;
 75→    modified_text?: string;
 76→    modified_type?: string;
 77→    modified_category?: string;
 78→    modified_structured_fields?: {
 79→        field_mappings?: FieldMapping[];
 80→        [key: string]: unknown;
 81→    };
 82→    comment?: string;
 83→    reject_reasons?: string[]; // predefined reject reason codes
 84→}
 85→
 86→export interface PdfUrlResponse {
 87→    url: string;
 88→    expires_in_minutes: number;
 89→}
 90→
 91→export interface AuditLogEntry {
 92→    id: string;
 93→    event_type: string;
 94→    actor_id: string | null;
 95→    target_type: string | null;
 96→    target_id: string | null;
 97→    details: Record<string, unknown>;
 98→    created_at: string;
 99→}
100→
101→export interface AuditLogListResponse {
102→    items: AuditLogEntry[];
103→    total: number;
104→    page: number;
105→    page_size: number;
106→    pages: number;
107→}
108→
109→export interface PendingSummary {
110→    pending_batches: number;
111→    pending_criteria: number;
112→    message: string;
113→}
114→
115→export interface ErrorProtocolItem {
116→    id: string;
117→    title: string;
118→    status: string;
119→}
120→
121→export interface PipelineSummary {
122→    criteria_extracted: number;
123→    protocols_in_grounding: number;
124→    error_count: number;
125→    error_protocols: ErrorProtocolItem[];
126→}
127→
128→// --- Hooks ---
129→
130→export function useBatchList(page: number, pageSize: number, status?: string) {
131→    const params = new URLSearchParams({
132→        page: String(page),
133→        page_size: String(pageSize),
134→    });
135→    if (status) {
136→        params.set('status', status);
137→    }
138→
139→    return useQuery({
140→        queryKey: ['review-batches', page, pageSize, status],
141→        queryFn: () => fetchApi<BatchListResponse>(`/reviews/batches?${params.toString()}`),
142→    });
143→}
144→
145→export function useBatchesByProtocol(protocolId: string) {
146→    return useQuery({
147→        queryKey: ['review-batches', 'protocol', protocolId],
148→        queryFn: () =>
149→            fetchApi<BatchListResponse>(
150→                `/reviews/batches?protocol_id=${encodeURIComponent(protocolId)}`
151→            ),
152→        enabled: !!protocolId,
153→    });
154→}
155→
156→export function useBatchCriteria(batchId: string, sortBy?: string, sortOrder?: string) {
157→    const params = new URLSearchParams();
158→    if (sortBy) {
159→        params.set('sort_by', sortBy);
160→    }
161→    if (sortOrder) {
162→        params.set('sort_order', sortOrder);
163→    }
164→    const queryString = params.toString();
165→    const url = queryString
166→        ? `/reviews/batches/${batchId}/criteria?${queryString}`
167→        : `/reviews/batches/${batchId}/criteria`;
168→
169→    return useQuery({
170→        queryKey: ['batch-criteria', batchId, sortBy, sortOrder],
171→        queryFn: () => fetchApi<Criterion[]>(url),
172→        enabled: Boolean(batchId),
173→    });
174→}
175→
176→export function useReviewAction() {
177→    const queryClient = useQueryClient();
178→
179→    return useMutation({
180→        mutationFn: ({ criteriaId, ...body }: ReviewActionRequest & { criteriaId: string }) =>
181→            fetchApi<Criterion>(`/reviews/criteria/${criteriaId}/action`, {
182→                method: 'POST',
183→                body: JSON.stringify(body),
184→            }),
185→        onSuccess: () => {
186→            queryClient.invalidateQueries({ queryKey: ['batch-criteria'] });
187→            queryClient.invalidateQueries({ queryKey: ['review-batches'] });
188→        },
189→    });
190→}
191→
192→export function usePdfUrl(protocolId: string) {
193→    return useQuery({
194→        queryKey: ['pdf-url', protocolId],
195→        queryFn: () => fetchApi<PdfUrlResponse>(`/reviews/protocols/${protocolId}/pdf-url`),
196→        enabled: Boolean(protocolId),
197→        staleTime: 50 * 60 * 1000,
198→    });
199→}
200→
201→export function useAuditLog(
202→    page: number,
203→    pageSize: number,
204→    targetType?: string,
205→    targetId?: string,
206→    batchId?: string
207→) {
208→    const params = new URLSearchParams({
209→        page: String(page),
210→        page_size: String(pageSize),
211→    });
212→    if (targetType) {
213→        params.set('target_type', targetType);
214→    }
215→    if (targetId) {
216→        params.set('target_id', targetId);
217→    }
218→    if (batchId) {
219→        params.set('batch_id', batchId);
220→    }
221→
222→    return useQuery({
223→        queryKey: ['audit-log', page, pageSize, targetType, targetId, batchId],
224→        queryFn: () => fetchApi<AuditLogListResponse>(`/reviews/audit-log?${params.toString()}`),
225→        staleTime: 30_000,
226→    });
227→}
228→
229→export function usePendingSummary() {
230→    return useQuery({
231→        queryKey: ['pending-summary'],
232→        queryFn: () => fetchApi<PendingSummary>('/reviews/pending-summary'),
233→        staleTime: 30 * 1000,
234→    });
235→}
236→
237→export function usePipelineSummary() {
238→    return useQuery({
239→        queryKey: ['pipeline-summary'],
240→        queryFn: () => fetchApi<PipelineSummary>('/reviews/pipeline-summary'),
241→        staleTime: 30 * 1000,
242→    });
243→}
