import * as AlertDialog from '@radix-ui/react-alert-dialog';
import * as Collapsible from '@radix-ui/react-collapsible';
import {
    AlertTriangle,
    ArrowLeft,
    BarChart3,
    Check,
    ChevronDown,
    ChevronRight,
    ClipboardList,
    Copy,
    History,
    Loader2,
    RefreshCw,
} from 'lucide-react';
import { useState } from 'react';
import { Link, useNavigate, useParams } from 'react-router-dom';

import { AgreementMetrics } from '../components/AgreementMetrics';
import { BatchTimeline } from '../components/BatchTimeline';
import { Button } from '../components/ui/Button';
import { useProtocol, useReExtractProtocol, useRetryProtocol } from '../hooks/useProtocols';
import { useBatchesByProtocol } from '../hooks/useReviews';
import { cn } from '../lib/utils';

const STATUS_COLORS: Record<string, string> = {
    uploaded: 'bg-blue-100 text-blue-800',
    processing: 'bg-blue-100 text-blue-800',
    extracting: 'bg-yellow-100 text-yellow-800',
    extraction_failed: 'bg-red-100 text-red-800',
    grounding: 'bg-cyan-100 text-cyan-800',
    grounding_failed: 'bg-orange-100 text-orange-800',
    pending_review: 'bg-indigo-100 text-indigo-800',
    complete: 'bg-green-100 text-green-800',
    dead_letter: 'bg-red-200 text-red-900',
    archived: 'bg-gray-100 text-gray-500',
    extracted: 'bg-green-100 text-green-800',
    reviewed: 'bg-purple-100 text-purple-800',
};

const STATUS_LABELS: Record<string, string> = {
    uploaded: 'Uploaded',
    processing: 'Processing',
    extracting: 'Extracting',
    extraction_failed: 'Extraction Failed',
    grounding: 'Grounding',
    grounding_failed: 'Grounding Failed',
    pending_review: 'Pending Review',
    complete: 'Complete',
    dead_letter: 'Dead Letter',
    archived: 'Archived',
    extracted: 'Extracted',
    reviewed: 'Reviewed',
};

// Statuses where the review button is visible (not actively processing)
const REVIEW_VISIBLE_STATUSES = new Set([
    'pending_review',
    'complete',
    'grounding_failed',   // may want to review partial results
]);

// Statuses where re-extraction is allowed (not actively processing)
const RE_EXTRACT_ALLOWED_STATUSES = new Set([
    'pending_review',
    'complete',
    'extraction_failed',
    'grounding_failed',
    'dead_letter',
]);

function StatusBadge({ status }: { status: string }) {
    return (
        <span
            className={cn(
                'inline-flex items-center rounded-full px-2.5 py-0.5 text-xs font-medium',
                STATUS_COLORS[status] ?? 'bg-gray-100 text-gray-800'
            )}
        >
            {STATUS_LABELS[status] ?? status}
        </span>
    );
}

function RetryButton({ protocolId }: { protocolId: string }) {
    const retryMutation = useRetryProtocol();

    return (
        <Button
            variant="outline"
            size="sm"
            onClick={(e) => {
                e.stopPropagation();
                retryMutation.mutate(protocolId);
            }}
            disabled={retryMutation.isPending}
            className="border-red-300 text-red-700 hover:bg-red-100"
        >
            {retryMutation.isPending ? (
                <>
                    <Loader2 className="h-4 w-4 mr-1 animate-spin" />
                    Retrying...
                </>
            ) : (
                'Retry Processing'
            )}
        </Button>
    );
}

interface ReExtractButtonProps {
    protocolId: string;
    protocolStatus: string;
}

function ReExtractButton({ protocolId, protocolStatus }: ReExtractButtonProps) {
    const reExtractMutation = useReExtractProtocol();
    const [error, setError] = useState<string | null>(null);

    const isDisabled =
        !RE_EXTRACT_ALLOWED_STATUSES.has(protocolStatus) || reExtractMutation.isPending;

    const handleConfirm = () => {
        setError(null);
        reExtractMutation.mutate(protocolId, {
            onError: (err) => {
                setError(err instanceof Error ? err.message : 'Re-extraction failed');
            },
        });
    };

    return (
        <div className="flex flex-col items-start gap-1">
            <AlertDialog.Root>
                <AlertDialog.Trigger asChild>
                    <Button variant="outline" size="sm" disabled={isDisabled}>
                        <RefreshCw className="h-4 w-4 mr-1.5" />
                        Re-extract Criteria
                    </Button>
                </AlertDialog.Trigger>
                <AlertDialog.Portal>
                    <AlertDialog.Overlay className="fixed inset-0 z-50 bg-black/50 data-[state=open]:animate-in data-[state=closed]:animate-out data-[state=closed]:fade-out-0 data-[state=open]:fade-in-0" />
                    <AlertDialog.Content className="fixed left-[50%] top-[50%] z-50 grid w-full max-w-lg translate-x-[-50%] translate-y-[-50%] gap-4 border bg-background p-6 shadow-lg sm:rounded-lg">
                        <AlertDialog.Title className="text-lg font-semibold">
                            Re-extract criteria?
                        </AlertDialog.Title>
                        <AlertDialog.Description className="text-sm text-muted-foreground">
                            Old batches will be saved but not available in the dashboard. Existing
                            reviews will be preserved and automatically applied to matching
                            criteria.
                        </AlertDialog.Description>
                        <div className="flex flex-col-reverse sm:flex-row sm:justify-end sm:space-x-2">
                            <AlertDialog.Cancel asChild>
                                <Button variant="outline">Cancel</Button>
                            </AlertDialog.Cancel>
                            <AlertDialog.Action asChild>
                                <Button onClick={handleConfirm}>Re-extract</Button>
                            </AlertDialog.Action>
                        </div>
                    </AlertDialog.Content>
                </AlertDialog.Portal>
            </AlertDialog.Root>
            {error && <p className="text-xs text-red-600">{error}</p>}
        </div>
    );
}

function CopyButton({ text }: { text: string }) {
    const [copied, setCopied] = useState(false);

    const handleCopy = async () => {
        try {
            await navigator.clipboard.writeText(text);
            setCopied(true);
            setTimeout(() => setCopied(false), 2000);
        } catch {
            // Clipboard API may not be available
        }
    };

    return (
        <button
            type="button"
            onClick={handleCopy}
            className="inline-flex items-center text-muted-foreground hover:text-foreground transition-colors"
            aria-label="Copy to clipboard"
        >
            {copied ? <Check className="h-4 w-4 text-green-500" /> : <Copy className="h-4 w-4" />}
        </button>
    );
}

interface InfoItemProps {
    label: string;
    children: React.ReactNode;
}

function InfoItem({ label, children }: InfoItemProps) {
    return (
        <div className="space-y-1">
            <dt className="text-sm font-medium text-muted-foreground">{label}</dt>
            <dd className="text-sm text-foreground">{children}</dd>
        </div>
    );
}

function QualityBar({ score }: { score: number }) {
    const percentage = Math.round(score * 100);
    let barColor = 'bg-red-500';
    let textColor = 'text-red-600';
    if (score > 0.7) {
        barColor = 'bg-green-500';
        textColor = 'text-green-600';
    } else if (score >= 0.3) {
        barColor = 'bg-yellow-500';
        textColor = 'text-yellow-600';
    }

    return (
        <div className="flex items-center gap-3">
            <div className="h-2.5 w-32 rounded-full bg-muted overflow-hidden">
                <div
                    className={cn('h-full rounded-full transition-all', barColor)}
                    style={{ width: `${percentage}%` }}
                />
            </div>
            <span className={cn('text-sm font-semibold', textColor)}>{percentage}%</span>
        </div>
    );
}

export default function ProtocolDetail() {
    const { id } = useParams<{ id: string }>();
    const navigate = useNavigate();

    const {
        data: protocol,
        isLoading,
        error,
    } = useProtocol(id ?? '', {
        refetchInterval: 5000,
        refetchIntervalInBackground: false,
    });
    const { data: batchData } = useBatchesByProtocol(id ?? '');

    // All hooks must be called before any conditional returns
    const [metricsOpen, setMetricsOpen] = useState(true);
    const [timelineOpen, setTimelineOpen] = useState(false);

    if (isLoading) {
        return (
            <div className="container mx-auto p-6 flex items-center justify-center py-16">
                <Loader2 className="h-8 w-8 animate-spin text-muted-foreground" />
            </div>
        );
    }

    if (error || !protocol) {
        return (
            <div className="container mx-auto p-6">
                <div className="flex flex-wrap items-center gap-3 mb-6">
                    <Link
                        to="/"
                        className="inline-flex items-center text-sm text-muted-foreground hover:text-foreground"
                    >
                        <ArrowLeft className="h-4 w-4 mr-1" />
                        Back to Dashboard
                    </Link>
                    <Link
                        to="/protocols"
                        className="inline-flex items-center text-sm text-muted-foreground hover:text-foreground"
                    >
                        <ArrowLeft className="h-4 w-4 mr-1" />
                        Back to Protocols
                    </Link>
                </div>
                <div className="rounded-lg border border-destructive/50 bg-destructive/10 p-6 text-center">
                    <p className="text-destructive">Protocol not found</p>
                </div>
            </div>
        );
    }

    // Extract quality metadata safely
    const qualityMeta = (protocol.metadata_?.quality ?? {}) as Record<string, unknown>;
    const encodingType = qualityMeta.encoding_type as string | undefined;
    const textExtractability = qualityMeta.text_extractability as number | undefined;
    const isLowQuality = qualityMeta.is_low_quality as boolean | undefined;

    const truncatedUri =
        protocol.file_uri.length > 50
            ? `${protocol.file_uri.slice(0, 25)}...${protocol.file_uri.slice(-22)}`
            : protocol.file_uri;

    const latestBatch = batchData?.items?.[0];

    // Show metrics/timeline sections only when protocol has batch data
    const hasBatch = !!latestBatch;

    return (
        <div className="container mx-auto p-6">
            {/* Back links */}
            <div className="flex flex-wrap items-center gap-3 mb-6">
                <Link
                    to="/"
                    className="inline-flex items-center text-sm text-muted-foreground hover:text-foreground"
                >
                    <ArrowLeft className="h-4 w-4 mr-1" />
                    Back to Dashboard
                </Link>
                <Link
                    to="/protocols"
                    className="inline-flex items-center text-sm text-muted-foreground hover:text-foreground"
                >
                    <ArrowLeft className="h-4 w-4 mr-1" />
                    Back to Protocols
                </Link>
            </div>

            {/* Title and status */}
            <div className="flex items-start justify-between mb-6">
                <div>
                    <h1 className="text-3xl font-bold text-foreground mb-2">{protocol.title}</h1>
                    <StatusBadge status={protocol.status} />
                </div>
                <ReExtractButton protocolId={protocol.id} protocolStatus={protocol.status} />
            </div>

            {/* Error Information */}
            {(protocol.status === 'extraction_failed' ||
                protocol.status === 'grounding_failed' ||
                protocol.status === 'dead_letter') && (
                <div className="rounded-lg border border-red-200 bg-red-50 p-4 mb-6">
                    <div className="flex items-start justify-between">
                        <div>
                            <h3 className="text-sm font-semibold text-red-800">
                                {protocol.status === 'dead_letter'
                                    ? 'Processing Failed (Retries Exhausted)'
                                    : protocol.status === 'extraction_failed'
                                      ? 'Extraction Failed'
                                      : 'Grounding Failed'}
                            </h3>
                            <p className="mt-1 text-sm text-red-700">
                                {protocol.error_reason ??
                                    'An unknown error occurred during processing.'}
                            </p>
                            {protocol.status === 'dead_letter' && (
                                <p className="mt-1 text-xs text-red-600">
                                    This protocol will be archived after 7 days.
                                </p>
                            )}
                        </div>
                        <RetryButton protocolId={protocol.id} />
                    </div>
                </div>
            )}

            {/* Re-extraction in progress banner */}
            {protocol.status === 'extracting' && (
                <div className="rounded-lg border border-blue-200 bg-blue-50 p-3 mb-6 flex items-center gap-2">
                    <Loader2 className="h-4 w-4 animate-spin text-blue-600 shrink-0" />
                    <p className="text-sm text-blue-700">
                        Re-extraction in progress. This typically takes 2-5 minutes.
                    </p>
                </div>
            )}

            {/* Generic processing in progress banner (uploaded/grounding) */}
            {(protocol.status === 'uploaded' || protocol.status === 'grounding') && (
                <div className="rounded-lg border border-blue-200 bg-blue-50 p-3 mb-6">
                    <p className="text-sm text-blue-700">
                        Processing in progress. This typically takes 2-5 minutes.
                    </p>
                </div>
            )}

            {/* Low quality warning */}
            {isLowQuality && (
                <div className="mb-6 flex items-start gap-3 rounded-lg border border-yellow-300 bg-yellow-50 p-4">
                    <AlertTriangle className="h-5 w-5 text-yellow-600 mt-0.5 shrink-0" />
                    <p className="text-sm text-yellow-800">
                        This PDF has low quality. Extraction results may be unreliable.
                    </p>
                </div>
            )}

            {/* Info grid */}
            <div className="rounded-lg border bg-card p-6 shadow-sm">
                <dl className="grid gap-6 md:grid-cols-2">
                    <InfoItem label="File URI">
                        <div className="flex items-center gap-2">
                            <span className="font-mono text-xs truncate" title={protocol.file_uri}>
                                {truncatedUri}
                            </span>
                            <CopyButton text={protocol.file_uri} />
                        </div>
                    </InfoItem>

                    <InfoItem label="Upload Date">
                        {new Date(protocol.created_at).toLocaleString()}
                    </InfoItem>

                    <InfoItem label="Page Count">{protocol.page_count ?? 'Not available'}</InfoItem>

                    <InfoItem label="Quality Score">
                        {protocol.quality_score !== null ? (
                            <QualityBar score={protocol.quality_score} />
                        ) : (
                            'Not available'
                        )}
                    </InfoItem>

                    <InfoItem label="Encoding Type">
                        {encodingType ? (
                            <span className="capitalize">{encodingType}</span>
                        ) : (
                            'Not available'
                        )}
                    </InfoItem>

                    <InfoItem label="Text Extractability">
                        {textExtractability !== undefined
                            ? `${Math.round(textExtractability * 100)}%`
                            : 'Not available'}
                    </InfoItem>
                </dl>
            </div>

            {/* Review Metrics section */}
            {hasBatch && latestBatch && (
                <div className="mt-6">
                    <Collapsible.Root open={metricsOpen} onOpenChange={setMetricsOpen}>
                        <Collapsible.Trigger asChild>
                            <button
                                type="button"
                                className="flex items-center gap-2 text-sm font-semibold text-foreground mb-2 hover:text-muted-foreground transition-colors"
                            >
                                <BarChart3 className="h-4 w-4" />
                                Review Metrics
                                {metricsOpen ? (
                                    <ChevronDown className="h-4 w-4" />
                                ) : (
                                    <ChevronRight className="h-4 w-4" />
                                )}
                            </button>
                        </Collapsible.Trigger>
                        <Collapsible.Content>
                            <AgreementMetrics batchId={latestBatch.id} />
                        </Collapsible.Content>
                    </Collapsible.Root>
                </div>
            )}

            {/* Batch History section */}
            {id && hasBatch && (
                <div className="mt-4">
                    <Collapsible.Root open={timelineOpen} onOpenChange={setTimelineOpen}>
                        <Collapsible.Trigger asChild>
                            <button
                                type="button"
                                className="flex items-center gap-2 text-sm font-semibold text-foreground mb-2 hover:text-muted-foreground transition-colors"
                            >
                                <History className="h-4 w-4" />
                                Batch History
                                {timelineOpen ? (
                                    <ChevronDown className="h-4 w-4" />
                                ) : (
                                    <ChevronRight className="h-4 w-4" />
                                )}
                            </button>
                        </Collapsible.Trigger>
                        <Collapsible.Content>
                            <BatchTimeline protocolId={id} />
                        </Collapsible.Content>
                    </Collapsible.Root>
                </div>
            )}

            {/* Actions */}
            <div className="mt-6 flex items-center gap-3">
                <Button variant="outline" asChild>
                    <Link to="/protocols">Back to List</Link>
                </Button>
                {latestBatch && protocol.status === 'pending_review' && (
                    <Button onClick={() => navigate(`/reviews/${latestBatch.id}`)}>
                        <ClipboardList className="h-4 w-4 mr-2" />
                        Review New Criteria ({latestBatch.criteria_count})
                    </Button>
                )}
                {latestBatch && protocol.status !== 'pending_review' && (
                    <Button onClick={() => navigate(`/reviews/${latestBatch.id}`)}>
                        <ClipboardList className="h-4 w-4 mr-2" />
                        Review Criteria ({latestBatch.criteria_count})
                    </Button>
                )}
            </div>
        </div>
    );
}

import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';

import { fetchApi } from '../lib/fetchApi';

// --- TypeScript interfaces ---

export interface CriteriaBatch {
    id: string;
    protocol_id: string;
    protocol_title: string;
    status:
        | 'pending_review'
        | 'in_progress'
        | 'entities_grounded'
        | 'reviewed'
        | 'approved'
        | 'rejected';
    extraction_model: string | null;
    criteria_count: number;
    reviewed_count: number;
    created_at: string;
    updated_at: string;
}

export interface BatchListResponse {
    items: CriteriaBatch[];
    total: number;
    page: number;
    page_size: number;
    pages: number;
}

// Field mapping for structured criteria edits (entity/relation/value triplet)
export interface FieldMapping {
    entity: string;
    entity_code?: string;
    entity_system?: string;
    omop_concept_id?: string;
    relation: string;
    value: unknown;
}

export interface CriterionEntity {
    id: string;
    entity_type: string;
    text: string;
    umls_cui: string | null;
    snomed_code: string | null;
    preferred_term: string | null;
    grounding_confidence: number | null;
}

export interface Criterion {
    id: string;
    batch_id: string;
    criteria_type: string;
    category: string | null;
    text: string;
    temporal_constraint: Record<string, unknown> | null;
    conditions: Record<string, unknown> | null;
    numeric_thresholds: Record<string, unknown> | null;
    assertion_status: string | null;
    confidence: number;
    source_section: string | null;
    page_number: number | null;
    review_status: string | null;
    entities: CriterionEntity[];
    created_at: string;
    updated_at: string;
}

export interface ReviewActionRequest {
    action: 'approve' | 'reject' | 'modify';
    reviewer_id: string;
    modified_text?: string;
    modified_type?: string;
    modified_category?: string;
    modified_structured_fields?: {
        field_mappings?: FieldMapping[];
        [key: string]: unknown;
    };
    comment?: string;
    reject_reasons?: string[]; // predefined reject reason codes
}

export interface PdfUrlResponse {
    url: string;
    expires_in_minutes: number;
}

export interface AuditLogEntry {
    id: string;
    event_type: string;
    actor_id: string | null;
    target_type: string | null;
    target_id: string | null;
    details: Record<string, unknown>;
    created_at: string;
}

export interface AuditLogListResponse {
    items: AuditLogEntry[];
    total: number;
    page: number;
    page_size: number;
    pages: number;
}

export interface PendingSummary {
    pending_batches: number;
    pending_criteria: number;
    message: string;
}

export interface ErrorProtocolItem {
    id: string;
    title: string;
    status: string;
}

export interface PipelineSummary {
    criteria_extracted: number;
    protocols_in_grounding: number;
    error_count: number;
    error_protocols: ErrorProtocolItem[];
}

// --- Hooks ---

export function useBatchList(page: number, pageSize: number, status?: string) {
    const params = new URLSearchParams({
        page: String(page),
        page_size: String(pageSize),
    });
    if (status) {
        params.set('status', status);
    }

    return useQuery({
        queryKey: ['review-batches', page, pageSize, status],
        queryFn: () => fetchApi<BatchListResponse>(`/reviews/batches?${params.toString()}`),
    });
}

export function useBatchesByProtocol(protocolId: string) {
    return useQuery({
        queryKey: ['review-batches', 'protocol', protocolId],
        queryFn: () =>
            fetchApi<BatchListResponse>(
                `/reviews/batches?protocol_id=${encodeURIComponent(protocolId)}`
            ),
        enabled: !!protocolId,
    });
}

export function useBatchCriteria(batchId: string, sortBy?: string, sortOrder?: string) {
    const params = new URLSearchParams();
    if (sortBy) {
        params.set('sort_by', sortBy);
    }
    if (sortOrder) {
        params.set('sort_order', sortOrder);
    }
    const queryString = params.toString();
    const url = queryString
        ? `/reviews/batches/${batchId}/criteria?${queryString}`
        : `/reviews/batches/${batchId}/criteria`;

    return useQuery({
        queryKey: ['batch-criteria', batchId, sortBy, sortOrder],
        queryFn: () => fetchApi<Criterion[]>(url),
        enabled: Boolean(batchId),
    });
}

export function useReviewAction() {
    const queryClient = useQueryClient();

    return useMutation({
        mutationFn: ({ criteriaId, ...body }: ReviewActionRequest & { criteriaId: string }) =>
            fetchApi<Criterion>(`/reviews/criteria/${criteriaId}/action`, {
                method: 'POST',
                body: JSON.stringify(body),
            }),
        onSuccess: () => {
            queryClient.invalidateQueries({ queryKey: ['batch-criteria'] });
            queryClient.invalidateQueries({ queryKey: ['review-batches'] });
        },
    });
}

export function usePdfUrl(protocolId: string) {
    return useQuery({
        queryKey: ['pdf-url', protocolId],
        queryFn: () => fetchApi<PdfUrlResponse>(`/reviews/protocols/${protocolId}/pdf-url`),
        enabled: Boolean(protocolId),
        staleTime: 50 * 60 * 1000,
    });
}

export function useAuditLog(
    page: number,
    pageSize: number,
    targetType?: string,
    targetId?: string,
    batchId?: string
) {
    const params = new URLSearchParams({
        page: String(page),
        page_size: String(pageSize),
    });
    if (targetType) {
        params.set('target_type', targetType);
    }
    if (targetId) {
        params.set('target_id', targetId);
    }
    if (batchId) {
        params.set('batch_id', batchId);
    }

    return useQuery({
        queryKey: ['audit-log', page, pageSize, targetType, targetId, batchId],
        queryFn: () => fetchApi<AuditLogListResponse>(`/reviews/audit-log?${params.toString()}`),
        staleTime: 30_000,
    });
}

export function usePendingSummary() {
    return useQuery({
        queryKey: ['pending-summary'],
        queryFn: () => fetchApi<PendingSummary>('/reviews/pending-summary'),
        staleTime: 30 * 1000,
    });
}

export function usePipelineSummary() {
    return useQuery({
        queryKey: ['pipeline-summary'],
        queryFn: () => fetchApi<PipelineSummary>('/reviews/pipeline-summary'),
        staleTime: 30 * 1000,
    });
}

