  1→import {
  2→    CheckCircle,
  3→    ChevronDown,
  4→    ChevronUp,
  5→    ExternalLink,
  6→    Loader2,
  7→    Pencil,
  8→    XCircle,
  9→} from 'lucide-react';
 10→import { useState } from 'react';
 11→
 12→import type { EntityActionRequest, EntityResponse } from '../hooks/useEntities';
 13→import { cn } from '../lib/utils';
 14→import EntityModifyDialog from './EntityModifyDialog';
 15→import { ErrorBadge, TerminologyBadge } from './TerminologyBadge';
 16→import { Button } from './ui/Button';
 17→
 18→interface EntityCardProps {
 19→    entity: EntityResponse;
 20→    onAction: (entityId: string, action: EntityActionRequest) => void;
 21→    isSubmitting: boolean;
 22→}
 23→
 24→export function EntityTypeBadge({ type }: { type: string }) {
 25→    const typeConfig: Record<string, { label: string; colorClass: string }> = {
 26→        Condition: { label: 'Condition', colorClass: 'bg-blue-100 text-blue-800' },
 27→        Medication: { label: 'Medication', colorClass: 'bg-purple-100 text-purple-800' },
 28→        Procedure: { label: 'Procedure', colorClass: 'bg-green-100 text-green-800' },
 29→        Lab_Value: { label: 'Lab Value', colorClass: 'bg-orange-100 text-orange-800' },
 30→        Demographic: { label: 'Demographic', colorClass: 'bg-gray-100 text-gray-800' },
 31→        Biomarker: { label: 'Biomarker', colorClass: 'bg-teal-100 text-teal-800' },
 32→    };
 33→
 34→    const config = typeConfig[type] || { label: type, colorClass: 'bg-gray-100 text-gray-800' };
 35→
 36→    return (
 37→        <span
 38→            className={cn(
 39→                'inline-flex items-center rounded-full px-2.5 py-0.5 text-xs font-medium',
 40→                config.colorClass
 41→            )}
 42→        >
 43→            {config.label}
 44→        </span>
 45→    );
 46→}
 47→
 48→export function GroundingConfidenceBadge({ confidence }: { confidence: number | null }) {
 49→    if (confidence === null) {
 50→        return (
 51→            <span className="inline-flex items-center rounded-full bg-gray-100 text-gray-800 px-2.5 py-0.5 text-xs font-medium">
 52→                No confidence
 53→            </span>
 54→        );
 55→    }
 56→
 57→    const percentage = Math.round(confidence * 100);
 58→
 59→    let label: string;
 60→    let colorClass: string;
 61→
 62→    if (confidence >= 0.85) {
 63→        label = 'High';
 64→        colorClass = 'bg-green-100 text-green-800';
 65→    } else if (confidence >= 0.7) {
 66→        label = 'Medium';
 67→        colorClass = 'bg-yellow-100 text-yellow-800';
 68→    } else {
 69→        label = 'Low';
 70→        colorClass = 'bg-red-100 text-red-800';
 71→    }
 72→
 73→    return (
 74→        <span
 75→            className={cn(
 76→                'inline-flex items-center rounded-full px-2.5 py-0.5 text-xs font-medium',
 77→                colorClass
 78→            )}
 79→            title={`Grounding confidence: ${percentage}%`}
 80→        >
 81→            {label} ({percentage}%)
 82→        </span>
 83→    );
 84→}
 85→
 86→export function ReviewStatusBadge({ status }: { status: string | null }) {
 87→    const statusConfig: Record<string, { label: string; colorClass: string }> = {
 88→        approved: { label: 'Approved', colorClass: 'bg-green-100 text-green-800' },
 89→        rejected: { label: 'Rejected', colorClass: 'bg-red-100 text-red-800' },
 90→        modified: { label: 'Modified', colorClass: 'bg-yellow-100 text-yellow-800' },
 91→    };
 92→
 93→    const config = status ? statusConfig[status] : null;
 94→    const label = config?.label ?? 'Pending';
 95→    const colorClass = config?.colorClass ?? 'bg-gray-100 text-gray-800';
 96→
 97→    return (
 98→        <span
 99→            className={cn(
100→                'inline-flex items-center rounded-full px-2.5 py-0.5 text-xs font-medium',
101→                colorClass
102→            )}
103→        >
104→            {label}
105→        </span>
106→    );
107→}
108→
109→/** Determine which systems are relevant for a given entity type. */
110→export function getRelevantSystems(entityType: string): string[] {
111→    switch (entityType) {
112→        case 'Medication':
113→            return ['rxnorm', 'umls'];
114→        case 'Condition':
115→            return ['icd10', 'snomed', 'umls'];
116→        case 'Lab_Value':
117→            return ['loinc', 'umls'];
118→        case 'Biomarker':
119→            return ['hpo', 'umls'];
120→        default:
121→            return ['snomed', 'umls'];
122→    }
123→}
124→
125→export default function EntityCard({ entity, onAction, isSubmitting }: EntityCardProps) {
126→    const [modifyDialogOpen, setModifyDialogOpen] = useState(false);
127→    const [contextOpen, setContextOpen] = useState(false);
128→
129→    const isLowConfidence = (entity.grounding_confidence ?? 0) < 0.7;
130→
131→    // Check if entity has any codes
132→    const hasCodes =
133→        entity.umls_cui ||
134→        entity.snomed_code ||
135→        entity.rxnorm_code ||
136→        entity.icd10_code ||
137→        entity.loinc_code ||
138→        entity.hpo_code;
139→
140→    function handleApprove() {
141→        onAction(entity.id, {
142→            action: 'approve',
143→            reviewer_id: 'current-user',
144→        });
145→    }
146→
147→    function handleReject() {
148→        onAction(entity.id, {
149→            action: 'reject',
150→            reviewer_id: 'current-user',
151→        });
152→    }
153→
154→    const contextText = entity.context_window?.text as string | undefined;
155→
156→    return (
157→        <div
158→            className={cn(
159→                'rounded-lg border bg-card p-4 shadow-sm',
160→                isLowConfidence && 'border-l-4 border-l-red-300'
161→            )}
162→        >
163→            {/* Header row */}
164→            <div className="flex flex-wrap items-center gap-2 mb-3">
165→                <EntityTypeBadge type={entity.entity_type} />
166→                <GroundingConfidenceBadge confidence={entity.grounding_confidence} />
167→                <ReviewStatusBadge status={entity.review_status} />
168→                {entity.grounding_method && (
169→                    <span
170→                        className="inline-flex items-center rounded-full bg-gray-100 px-2.5 py-0.5 text-xs text-gray-600"
171→                        title={`Grounding method: ${entity.grounding_method}`}
172→                    >
173→                        {entity.grounding_method}
174→                    </span>
175→                )}
176→            </div>
177→
178→            {/* Entity text */}
179→            <p className="text-sm font-medium text-foreground mb-3">{entity.text}</p>
180→
181→            {/* Multi-code badge section */}
182→            <div className="flex flex-wrap gap-1.5 mb-3">
183→                {entity.rxnorm_code && (
184→                    <TerminologyBadge system="rxnorm" code={entity.rxnorm_code} />
185→                )}
186→                {entity.icd10_code && <TerminologyBadge system="icd10" code={entity.icd10_code} />}
187→                {entity.snomed_code && (
188→                    <TerminologyBadge
189→                        system="snomed"
190→                        code={entity.snomed_code}
191→                        display={entity.preferred_term ?? undefined}
192→                    />
193→                )}
194→                {entity.loinc_code && <TerminologyBadge system="loinc" code={entity.loinc_code} />}
195→                {entity.hpo_code && <TerminologyBadge system="hpo" code={entity.hpo_code} />}
196→                {entity.umls_cui && (
197→                    <a
198→                        href={`https://uts.nlm.nih.gov/cts/umls/concept/${entity.umls_cui}`}
199→                        target="_blank"
200→                        rel="noopener noreferrer"
201→                        className="inline-flex items-center gap-1 rounded-full border border-indigo-300 bg-indigo-100 px-2.5 py-0.5 text-xs font-medium text-indigo-800 hover:bg-indigo-200 transition-colors"
202→                    >
203→                        CUI: {entity.umls_cui}
204→                        <ExternalLink className="h-3 w-3" />
205→                    </a>
206→                )}
207→                {entity.grounding_error && <ErrorBadge errorReason={entity.grounding_error} />}
208→                {!hasCodes && !entity.grounding_error && (
209→                    <span className="inline-flex items-center rounded-full border border-gray-200 bg-gray-100 px-2.5 py-0.5 text-xs font-medium text-gray-500">
210→                        Not grounded
211→                    </span>
212→                )}
213→            </div>
214→
215→            {/* Context window (collapsible) */}
216→            {contextText && (
217→                <div className="border-t pt-3 mb-3">
218→                    <button
219→                        type="button"
220→                        className="flex items-center gap-2 text-sm font-medium text-muted-foreground hover:text-foreground transition-colors"
221→                        onClick={() => setContextOpen(!contextOpen)}
222→                    >
223→                        {contextOpen ? (
224→                            <ChevronUp className="h-4 w-4" />
225→                        ) : (
226→                            <ChevronDown className="h-4 w-4" />
227→                        )}
228→                        Context
229→                    </button>
230→                    {contextOpen && (
231→                        <p className="mt-2 text-xs text-muted-foreground bg-muted/30 rounded-md p-2">
232→                            {contextText}
233→                        </p>
234→                    )}
235→                </div>
236→            )}
237→
238→            {/* Action buttons */}
239→            <div className="flex items-center gap-2 pt-2 border-t">
240→                <Button
241→                    size="sm"
242→                    variant="outline"
243→                    className="text-green-700 border-green-300 hover:bg-green-50"
244→                    onClick={handleApprove}
245→                    disabled={isSubmitting || entity.review_status === 'approved'}
246→                >
247→                    {isSubmitting ? (
248→                        <Loader2 className="h-4 w-4 animate-spin mr-1" />
249→                    ) : (
250→                        <CheckCircle className="h-4 w-4 mr-1" />
251→                    )}
252→                    Approve
253→                </Button>
254→                <Button
255→                    size="sm"
256→                    variant="outline"
257→                    className="text-red-700 border-red-300 hover:bg-red-50"
258→                    onClick={handleReject}
259→                    disabled={isSubmitting || entity.review_status === 'rejected'}
260→                >
261→                    {isSubmitting ? (
262→                        <Loader2 className="h-4 w-4 animate-spin mr-1" />
263→                    ) : (
264→                        <XCircle className="h-4 w-4 mr-1" />
265→                    )}
266→                    Reject
267→                </Button>
268→                <Button
269→                    size="sm"
270→                    variant="outline"
271→                    className="text-blue-700 border-blue-300 hover:bg-blue-50"
272→                    onClick={() => setModifyDialogOpen(true)}
273→                    disabled={isSubmitting}
274→                >
275→                    <Pencil className="h-4 w-4 mr-1" />
276→                    Modify
277→                </Button>
278→            </div>
279→
280→            <EntityModifyDialog
281→                open={modifyDialogOpen}
282→                onOpenChange={setModifyDialogOpen}
283→                entity={entity}
284→                onSave={(payload) => {
285→                    onAction(entity.id, {
286→                        action: 'modify',
287→                        reviewer_id: 'current-user',
288→                        ...payload,
289→                    });
290→                }}
291→                isSubmitting={isSubmitting}
292→            />
293→        </div>
294→    );
295→}
